import math
import numpy as np
from scipy.optimize import least_squares

_params = None

def _predict_with(params, row):
    vmax, rho, c_loc = params
    u = max(0.0, float(row['u_now']))
    s = float(row['s_grad'])
    u_n = u  # characteristic tau scale is 1.0
    base = vmax * (1.0 - rho * s / (1.0 + s)) * (u_n / (1.2 + u_n))
    return base + c_loc * math.sqrt(u_n)

def fit(train_rows):
    global _params
    y = np.asarray([float(r['y']) for r in train_rows], dtype=float)
    def residual(p):
        return np.asarray([_predict_with(p, r) for r in train_rows]) - y
    result = least_squares(residual, x0=np.array([4.0, 0.7, 0.5]), max_nfev=20000)
    _params = result.x
    return _params

def predict(row) -> float:
    if _params is None:
        raise RuntimeError('fit(train_rows) must be called before predict(row)')
    return float(_predict_with(_params, row))
